<script setup lang="ts">
definePageMeta({ layout: 'admin' })
const { data, pending, error, refresh } = await useFetch<any>('/api/admin/customers', { server: false, retry: false })
const search = ref('')
const selectedId = ref<number | null>(null)
const customers = computed(() => {
  const rows = [...(data.value?.customers || [])].sort((a: any, b: any) => Number(b.totalSpent) - Number(a.totalSpent))
  const term = search.value.trim().toLowerCase()
  return term ? rows.filter((item: any) => `${item.name} ${item.email} ${item.phone}`.toLowerCase().includes(term)) : rows
})
const selected = computed(() => data.value?.customers?.find((item: any) => item.id === selectedId.value) || null)
const totalSpent = computed(() => (data.value?.customers || []).reduce((sum: number, customer: any) => sum + Number(customer.totalSpent), 0))
function exportCsv() {
  const header = ['ชื่อลูกค้า', 'อีเมล', 'เบอร์โทรศัพท์', 'จำนวนคำสั่งซื้อ', 'ยอดสั่งซื้อรวม']
  const rows = customers.value.map((item: any) => [item.name, item.email, item.phone, item.ordersCount, item.totalSpent])
  const csv = [header, ...rows].map((row) => row.map((value: any) => `"${String(value ?? '').replaceAll('"', '""')}"`).join(',')).join('\n')
  const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8' })
  const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'anchalee-customers.csv'; link.click(); URL.revokeObjectURL(link.href)
}
</script>

<template>
  <div class="admin-page-wrap"><div class="admin-page-heading"><div><span class="section-kicker">PEOPLE WHO LOVE YOUR FRAMES</span><h1>ลูกค้าของเรา <span class="heading-count">{{ data?.customers?.length || 0 }}</span></h1><p>ดูข้อมูลผู้ซื้อและยอดสั่งซื้อได้ในที่เดียว</p></div><button class="button button-outline" @click="exportCsv"><AppIcon name="receipt" :size="16"/> ดาวน์โหลดรายชื่อลูกค้า</button></div>
    <section class="stat-grid compact-stat-grid"><article class="mini-stat-card"><span class="mini-stat-icon mini-purple"><AppIcon name="users" :size="18"/></span><span><small>ลูกค้าทั้งหมด</small><strong>{{ data?.customers?.length || 0 }} <i>คน</i></strong></span></article><article class="mini-stat-card"><span class="mini-stat-icon mini-green"><AppIcon name="circle-dollar" :size="18"/></span><span><small>ยอดสั่งซื้อรวม</small><strong>฿{{ formatBaht(totalSpent) }}</strong></span></article><article class="mini-stat-card"><span class="mini-stat-icon mini-blue"><AppIcon name="heart" :size="18"/></span><span><small>ลูกค้ากลับมาซื้อซ้ำ</small><strong>{{ (data?.customers || []).filter((item: any) => item.ordersCount > 1).length }} <i>คน</i></strong></span></article></section>
    <section class="admin-panel customers-panel"><div class="customer-toolbar"><div><span class="section-kicker">CUSTOMER DIRECTORY</span><h2>รายชื่อลูกค้า</h2></div><label class="admin-search"><AppIcon name="search" :size="17"/><input v-model="search" type="search" placeholder="ค้นหาชื่อ อีเมล หรือเบอร์โทร..."/></label></div><div v-if="pending" class="admin-loading-card"><span class="loading-spinner"/> กำลังโหลดรายชื่อลูกค้า...</div><div v-else-if="error" class="admin-error-card"><AppIcon name="alert" :size="20"/> โหลดข้อมูลลูกค้าไม่สำเร็จ <button class="button button-outline" @click="refresh()">ลองอีกครั้ง</button></div><div v-else-if="customers.length" class="table-scroll"><table class="admin-table customers-table"><thead><tr><th>ลูกค้า</th><th>เบอร์โทรศัพท์</th><th>ออเดอร์</th><th>ยอดสั่งซื้อรวม</th><th>เข้าร่วมเมื่อ</th><th/></tr></thead><tbody><tr v-for="customer in customers" :key="customer.id" class="clickable-row" @click="selectedId = customer.id"><td><div class="table-customer"><span class="customer-avatar-small customer-avatar-colored">{{ customer.name.slice(-1) }}</span><span><strong>{{ customer.name }}</strong><small>{{ customer.email || 'ไม่ได้ระบุอีเมล' }}</small></span></div></td><td>{{ customer.phone }}</td><td><span class="customer-order-count">{{ customer.ordersCount }} <small>คำสั่งซื้อ</small></span></td><td><strong>฿{{ formatBaht(customer.totalSpent) }}</strong></td><td>{{ formatShortDate(customer.createdAt) }}</td><td><button class="table-action-button" title="ดูข้อมูลลูกค้า"><AppIcon name="chevron-right" :size="16"/></button></td></tr></tbody></table></div><div v-else class="panel-empty"><AppIcon name="users" :size="24"/><span>ไม่พบข้อมูลลูกค้า</span></div><div class="table-footer"><span>แสดง {{ customers.length }} จาก {{ data?.customers?.length || 0 }} คน</span><span><AppIcon name="shield" :size="14"/> ข้อมูลลูกค้าสำหรับการจัดการคำสั่งซื้อ</span></div></section>
    <AdminModal :model-value="!!selected" :title="selected?.name || 'ข้อมูลลูกค้า'" subtitle="ข้อมูลที่ใช้จัดการคำสั่งซื้อและการจัดส่ง" @update:model-value="(value) => { if (!value) selectedId = null }"><template v-if="selected"><div class="customer-profile-card"><span class="customer-profile-avatar">{{ selected.name.slice(-1) }}</span><div><strong>{{ selected.name }}</strong><small>ลูกค้า Anchalee Frame</small></div><span class="customer-profile-spent">฿{{ formatBaht(selected.totalSpent) }}<small>ยอดสั่งซื้อรวม</small></span></div><div class="customer-detail-list"><div><span><AppIcon name="phone" :size="16"/> เบอร์โทรศัพท์</span><strong>{{ selected.phone }}</strong></div><div><span><AppIcon name="mail" :size="16"/> อีเมล</span><strong>{{ selected.email || 'ไม่ระบุ' }}</strong></div><div><span><AppIcon name="receipt" :size="16"/> คำสั่งซื้อ</span><strong>{{ selected.ordersCount }} รายการ</strong></div><div><span><AppIcon name="calendar" :size="16"/> ลูกค้าตั้งแต่</span><strong>{{ formatDate(selected.createdAt) }}</strong></div><div class="customer-address-detail"><span><AppIcon name="pin" :size="16"/> ที่อยู่จัดส่งล่าสุด</span><strong>{{ selected.address || 'ยังไม่มีข้อมูลที่อยู่' }}</strong></div></div><div class="modal-actions"><NuxtLink class="button button-outline" :to="`/admin/orders?q=${encodeURIComponent(selected.phone)}`" @click="selectedId = null">ดูคำสั่งซื้อของลูกค้า <AppIcon name="arrow-right" :size="15"/></NuxtLink><button class="button button-primary" @click="selectedId = null">เสร็จสิ้น <AppIcon name="check" :size="15"/></button></div></template></AdminModal>
  </div>
</template>
